import type {
  Entity,
  EntityCategory,
  Placement,
  Branch,
  Workbook,
  WorkbookFile,
  WorkspaceState,
  RecentEntityIndexEntry,
  WorkspaceSourceType,
} from '../types/schema';

export interface TargetYellowLead {
  targetEntityId: string;
  targetEntityName: string;
  targetCategory: EntityCategory;
  note: string;
}

export interface EntitySearchResult {
  entityId: string;
  name: string;
  category: EntityCategory;
  source: 'current_workspace' | 'external_workspace';
  workspaceName?: string;
  workbookTitle?: string;
  historySummary: string;
  confirmedYellowOutCount: number;
  targetYellowLeads: TargetYellowLead[];
}

/**
 * Builds or updates the cross-workspace recent index from a workspace.
 * Pure TypeScript function with zero DOM/storage dependencies.
 */
export function updateRecentEntitiesIndex(
  workspace: WorkspaceState,
  workspaceName: string,
  sourceType: WorkspaceSourceType = 'local',
  existingIndex: RecentEntityIndexEntry[] = []
): RecentEntityIndexEntry[] {
  const indexMap = new Map<string, RecentEntityIndexEntry>();

  for (const entry of existingIndex) {
    indexMap.set(entry.entityId, entry);
  }

  const now = new Date().toISOString();
  const wsId = workspace.workspaceId || 'ws_default';

  for (const [entityId, entity] of Object.entries(workspace.entities)) {
    const normalizedName = normalizeEntityName(entity.name);

    // Collect workbook mentions
    const mentions: Array<{ workbookId: string; workbookTitle: string; lastSeenAt: string }> = [];
    for (const plc of Object.values(workspace.placements)) {
      if (plc.entityId === entityId && plc.workbookId) {
        const wb = workspace.workbooks[plc.workbookId];
        mentions.push({
          workbookId: plc.workbookId,
          workbookTitle: wb?.title || 'Untitled Workbook',
          lastSeenAt: now,
        });
      }
    }

    // Collect confirmed outgoing yellow referral leads
    const targetYellowLeads: TargetYellowLead[] = [];
    const seenTargetIds = new Set<string>();
    const matchingPlacements = Object.values(workspace.placements).filter((p) => p.entityId === entityId);

    for (const plc of matchingPlacements) {
      for (const br of Object.values(workspace.branches)) {
        if (
          br.sourcePlacementId === plc.placementId &&
          br.type === 'yellow' &&
          br.status === 'tick'
        ) {
          const targetPlc = workspace.placements[br.targetPlacementId];
          if (targetPlc) {
            const targetEnt = workspace.entities[targetPlc.entityId];
            if (targetEnt && !seenTargetIds.has(targetEnt.entityId)) {
              seenTargetIds.add(targetEnt.entityId);
              targetYellowLeads.push({
                targetEntityId: targetEnt.entityId,
                targetEntityName: targetEnt.name,
                targetCategory: targetEnt.category,
                note: br.note || 'Proven referral gateway',
              });
            }
          }
        }
      }
    }

    const confirmedYellowOutCount = targetYellowLeads.length;
    const historySummary = confirmedYellowOutCount > 0
      ? `Proven bridge with ${confirmedYellowOutCount} confirmed referral${confirmedYellowOutCount > 1 ? 's' : ''}`
      : entity.pointsOfContact && entity.pointsOfContact.length > 0
      ? `${entity.pointsOfContact.length} documented point${entity.pointsOfContact.length > 1 ? 's' : ''} of contact`
      : `Found in ${workspaceName} [${sourceType === 'gdrive' ? 'Google Drive' : 'Local'}]`;

    indexMap.set(entityId, {
      entityId,
      name: entity.name,
      normalizedName,
      category: entity.category,
      workspaceId: wsId,
      workspaceName,
      sourceType,
      workbookMentions: mentions.length > 0 ? mentions : [
        {
          workbookId: workspace.activeWorkbookId,
          workbookTitle: workspace.workbooks[workspace.activeWorkbookId]?.title || 'Active Workbook',
          lastSeenAt: now,
        },
      ],
      confirmedYellowOutCount,
      targetYellowLeads,
      historySummary,
    });
  }

  return Array.from(indexMap.values());
}
export function normalizeEntityName(name: string): string {
  return name.trim().toLowerCase().replace(/[^a-z0-9\s]/g, '');
}

/**
 * Searches across current workspace entities and device-local recent cross-workspace index.
 * Gated at query length >= 3 characters.
 */
export function searchCrossWorkbookEntities(
  query: string,
  currentEntities: Record<string, Entity>,
  recentIndex: RecentEntityIndexEntry[] = [],
  currentWorkbooks: Record<string, WorkbookFile | Workbook> = {},
  currentBranches: Record<string, Branch> = {},
  currentPlacements: Record<string, Placement> = {}
): EntitySearchResult[] {
  const trimmed = query.trim();
  if (trimmed.length < 3) {
    return [];
  }

  const queryLower = trimmed.toLowerCase();
  const queryNormalized = normalizeEntityName(trimmed);
  const results: EntitySearchResult[] = [];
  const seenEntityNames = new Set<string>();

  // 1. Search current workspace entities
  for (const [entityId, entity] of Object.entries(currentEntities)) {
    const entNameLower = entity.name.toLowerCase();
    const entNameNorm = normalizeEntityName(entity.name);

    if (entNameLower.includes(queryLower) || entNameNorm.includes(queryNormalized)) {
      seenEntityNames.add(entNameNorm);

      // Find all placements for this entity
      const matchingPlacements = Object.values(currentPlacements).filter(
        (p) => p.entityId === entityId
      );

      // Find confirmed outgoing yellow bridges from this entity's placements
      const targetYellowLeads: TargetYellowLead[] = [];
      const seenTargetIds = new Set<string>();

      for (const plc of matchingPlacements) {
        for (const br of Object.values(currentBranches)) {
          if (
            br.sourcePlacementId === plc.placementId &&
            br.type === 'yellow' &&
            br.status === 'tick'
          ) {
            const targetPlc = currentPlacements[br.targetPlacementId];
            if (targetPlc) {
              const targetEnt = currentEntities[targetPlc.entityId];
              if (targetEnt && !seenTargetIds.has(targetEnt.entityId)) {
                seenTargetIds.add(targetEnt.entityId);
                targetYellowLeads.push({
                  targetEntityId: targetEnt.entityId,
                  targetEntityName: targetEnt.name,
                  targetCategory: targetEnt.category,
                  note: br.note || 'Proven referral gateway',
                });
              }
            }
          }
        }
      }

      // Determine active workbook context
      const firstPlc = matchingPlacements[0];
      const wbTitle = firstPlc?.workbookId && currentWorkbooks[firstPlc.workbookId]
        ? currentWorkbooks[firstPlc.workbookId].title
        : undefined;

      const historySummary = targetYellowLeads.length > 0
        ? `Proven bridge with ${targetYellowLeads.length} confirmed referral${targetYellowLeads.length > 1 ? 's' : ''}`
        : entity.pointsOfContact && entity.pointsOfContact.length > 0
        ? `${entity.pointsOfContact.length} documented point${entity.pointsOfContact.length > 1 ? 's' : ''} of contact`
        : 'Registered organization in current workspace';

      results.push({
        entityId,
        name: entity.name,
        category: entity.category,
        source: 'current_workspace',
        workbookTitle: wbTitle,
        historySummary,
        confirmedYellowOutCount: targetYellowLeads.length,
        targetYellowLeads,
      });
    }
  }

  // 2. Search external recent index
  for (const entry of recentIndex) {
    const entryNameNorm = normalizeEntityName(entry.name);
    if (seenEntityNames.has(entryNameNorm)) {
      continue; // Skip if already present in current workspace results
    }

    if (
      entry.name.toLowerCase().includes(queryLower) ||
      entry.normalizedName.includes(queryNormalized)
    ) {
      seenEntityNames.add(entryNameNorm);
      const lastMention = entry.workbookMentions[0];
      const targetYellowLeads: TargetYellowLead[] = entry.targetYellowLeads || [];
      const confirmedYellowOutCount = entry.confirmedYellowOutCount ?? targetYellowLeads.length;
      const historySummary = entry.historySummary ||
        (confirmedYellowOutCount > 0
          ? `Proven referral gateway with ${confirmedYellowOutCount} confirmed lead${confirmedYellowOutCount > 1 ? 's' : ''} in ${entry.workspaceName}`
          : `Found in ${entry.workspaceName} [${entry.sourceType === 'gdrive' ? 'Google Drive' : 'Local'}]`);

      results.push({
        entityId: entry.entityId,
        name: entry.name,
        category: entry.category,
        source: 'external_workspace',
        workspaceName: entry.workspaceName,
        workbookTitle: lastMention?.workbookTitle,
        historySummary,
        confirmedYellowOutCount,
        targetYellowLeads,
      });
    }
  }

  return results;
}

export * from './metrics';
export * from './parallelEdges';
export * from './overlap';
export * from './layout';
export * from './utility';
export * from './risk';
export * from './isolation';

/**
 * QualCount: Visual Multiplex Partnership Management System
 * Pure Isolation Mode & Marquee Filtering Engine (src/engine/isolation.ts)
 * 
 * Provides deterministic topology filtering for Illustrator-style isolation mode.
 * When a node or branch is isolated, non-connected elements are visually dimmed.
 * When a user draws a marquee selection box in isolation mode, candidates are strictly
 * filtered so that ONLY highlighted (isolated & connected) elements are selected.
 * 
 * Pure TypeScript (zero DOM/React/storage dependencies).
 */

import type { Branch } from '../types/schema';

export type IsolatedElement = {
  type: 'node' | 'branch';
  id: string;
} | null;

/**
 * Returns a Set of placement IDs that are highlighted (not dimmed) in isolation mode.
 * If isolation mode is not active (isolatedElement is null), returns null (indicating all nodes are valid).
 * 
 * - When a node is isolated: contains the target node and all 1-hop connected neighbors (both incoming and outgoing).
 * - When a branch is isolated: contains the source and target placement endpoints.
 * 
 * @param isolatedElement Currently isolated node or branch, or null
 * @param branches All branches in the workspace (Record or Array)
 * @param activeWorkbookId Optional active workbook filter
 */
export function getIsolatedHighlightedPlacementIds(
  isolatedElement: IsolatedElement,
  branches: Record<string, Branch> | Branch[],
  activeWorkbookId?: string
): Set<string> | null {
  if (!isolatedElement) return null;

  const branchList = Array.isArray(branches) ? branches : Object.values(branches);
  const relevantBranches = activeWorkbookId
    ? branchList.filter((b) => b.workbookId === activeWorkbookId)
    : branchList;

  const highlighted = new Set<string>();

  if (isolatedElement.type === 'node') {
    const targetId = isolatedElement.id;
    highlighted.add(targetId);
    for (const b of relevantBranches) {
      if (b.sourcePlacementId === targetId) {
        highlighted.add(b.targetPlacementId);
      }
      if (b.targetPlacementId === targetId) {
        highlighted.add(b.sourcePlacementId);
      }
    }
  } else if (isolatedElement.type === 'branch') {
    const branch = relevantBranches.find((b) => b.branchId === isolatedElement.id);
    if (branch) {
      highlighted.add(branch.sourcePlacementId);
      highlighted.add(branch.targetPlacementId);
    }
  }

  return highlighted;
}

/**
 * Returns a Set of branch IDs that are highlighted (not dimmed) in isolation mode.
 * If isolation mode is not active, returns null (indicating all branches are valid).
 * 
 * - When a node is isolated: contains all branches connected to that node.
 * - When a branch is isolated: contains only that isolated branch.
 * 
 * @param isolatedElement Currently isolated node or branch, or null
 * @param branches All branches in the workspace (Record or Array)
 * @param activeWorkbookId Optional active workbook filter
 */
export function getIsolatedHighlightedBranchIds(
  isolatedElement: IsolatedElement,
  branches: Record<string, Branch> | Branch[],
  activeWorkbookId?: string
): Set<string> | null {
  if (!isolatedElement) return null;

  const branchList = Array.isArray(branches) ? branches : Object.values(branches);
  const relevantBranches = activeWorkbookId
    ? branchList.filter((b) => b.workbookId === activeWorkbookId)
    : branchList;

  const highlighted = new Set<string>();

  if (isolatedElement.type === 'branch') {
    highlighted.add(isolatedElement.id);
  } else if (isolatedElement.type === 'node') {
    const targetId = isolatedElement.id;
    for (const b of relevantBranches) {
      if (b.sourcePlacementId === targetId || b.targetPlacementId === targetId) {
        highlighted.add(b.branchId);
      }
    }
  }

  return highlighted;
}

/**
 * Checks whether a given placement is dimmed under the active isolation mode.
 */
export function isPlacementDimmedInIsolation(
  placementId: string,
  isolatedElement: IsolatedElement,
  branches: Record<string, Branch> | Branch[],
  activeWorkbookId?: string
): boolean {
  if (!isolatedElement) return false;
  const highlighted = getIsolatedHighlightedPlacementIds(isolatedElement, branches, activeWorkbookId);
  return highlighted !== null && !highlighted.has(placementId);
}

/**
 * Checks whether a given branch is dimmed under the active isolation mode.
 */
export function isBranchDimmedInIsolation(
  branchId: string,
  isolatedElement: IsolatedElement,
  branches: Record<string, Branch> | Branch[],
  activeWorkbookId?: string
): boolean {
  if (!isolatedElement) return false;
  const highlighted = getIsolatedHighlightedBranchIds(isolatedElement, branches, activeWorkbookId);
  return highlighted !== null && !highlighted.has(branchId);
}

/**
 * Filters marquee candidate selections against isolation mode rules.
 * Any dimmed / non-isolated nodes and branches are stripped out.
 * 
 * @param candidates Object containing touched placementIds and branchIds
 * @param isolatedElement Current isolation element or null
 * @param branches All branches in workspace
 * @param activeWorkbookId Optional active workbook filter
 * @returns Filtered selection containing ONLY highlighted/isolated elements
 */
export function filterSelectionByIsolation(
  candidates: { placementIds: string[]; branchIds: string[] },
  isolatedElement: IsolatedElement,
  branches: Record<string, Branch> | Branch[],
  activeWorkbookId?: string
): { placementIds: string[]; branchIds: string[] } {
  if (!isolatedElement) {
    return candidates;
  }

  const highlightedPlacements = getIsolatedHighlightedPlacementIds(
    isolatedElement,
    branches,
    activeWorkbookId
  );
  const highlightedBranches = getIsolatedHighlightedBranchIds(
    isolatedElement,
    branches,
    activeWorkbookId
  );

  const filteredPlacements = highlightedPlacements !== null
    ? candidates.placementIds.filter((id) => highlightedPlacements.has(id))
    : candidates.placementIds;

  const filteredBranches = highlightedBranches !== null
    ? candidates.branchIds.filter((id) => highlightedBranches.has(id))
    : candidates.branchIds;

  return {
    placementIds: filteredPlacements,
    branchIds: filteredBranches,
  };
}

/**
 * QualCount: Visual Multiplex Partnership Management System
 * Pure Bottom-to-Top ELK Layout Engine (src/engine/layout.ts)
 * 
 * Computes a discrete Sugiyama layered hierarchical layout using elkjs.
 * Configured explicitly with elk.direction: "UP" so the root NGO sits at the
 * base (highest y) and target policy agencies crown the top (lowest y).
 * 
 * Read-Only Topology Guarantee: Placements and branches are strictly read-only.
 * Isolated / zero-degree nodes are staged gracefully on a baseline rack below
 * Tier 0 without crashing ELK.
 * 
 * Pure TypeScript (zero DOM/React/storage dependencies).
 */

import ELK from 'elkjs/lib/elk.bundled.js';
import type { Placement, Branch } from '../types/schema';

// ---------------------------------------------------------------------------
// ELK Layout Engine Configuration
// ---------------------------------------------------------------------------

const elk = new ELK();

export const DEFAULT_LAYOUT_OPTIONS: Record<string, string> = {
  'elk.algorithm': 'layered',
  'elk.direction': 'UP',
  'elk.edgeRouting': 'SPLINES',
  'elk.spacing.nodeNode': '72',
  'elk.layered.spacing.nodeNodeBetweenLayers': '125',
  'elk.layered.crossingMinimization.strategy': 'LAYER_SWEEP',
  'elk.layered.nodePlacement.strategy': 'NETWORK_SIMPLEX',
};

// ---------------------------------------------------------------------------
// Hierarchical Layout Function
// ---------------------------------------------------------------------------

/**
 * Computes bottom-to-top hierarchical coordinates for all placements in the workbook.
 * 
 * @param placements Placement records dictionary
 * @param branches Branch records dictionary
 * @param activeWorkbookId Optional workbook ID filter
 * @returns Map of placementId -> { x, y } coordinates
 */
export async function computeHierarchicalLayout(
  placements: Record<string, Placement>,
  branches: Record<string, Branch>,
  activeWorkbookId?: string,
  direction: 'UP' | 'DOWN' | 'RIGHT' | 'LEFT' = 'UP'
): Promise<Record<string, { x: number; y: number }>> {
  const placementList = Object.values(placements).filter(
    (p) => !activeWorkbookId || p.workbookId === activeWorkbookId
  );
  const branchList = Object.values(branches).filter(
    (b) => !activeWorkbookId || b.workbookId === activeWorkbookId
  );

  if (placementList.length === 0) {
    return {};
  }

  const placementIdSet = new Set(placementList.map((p) => p.placementId));

  // Determine connected vs. isolated placements
  const connectedIdSet = new Set<string>();
  const validBranches: Branch[] = [];

  for (const b of branchList) {
    if (
      placementIdSet.has(b.sourcePlacementId) &&
      placementIdSet.has(b.targetPlacementId)
    ) {
      connectedIdSet.add(b.sourcePlacementId);
      connectedIdSet.add(b.targetPlacementId);
      validBranches.push(b);
    }
  }

  const connectedPlacements = placementList.filter((p) =>
    connectedIdSet.has(p.placementId)
  );
  const isolatedPlacements = placementList.filter(
    (p) => !connectedIdSet.has(p.placementId)
  );

  const resultPositions: Record<string, { x: number; y: number }> = {};

  let minX = 100;
  let maxY = 100;

  // 1. Layout connected placements with ELK
  if (connectedPlacements.length > 0) {
    const layoutOptions: Record<string, string> = {
      ...DEFAULT_LAYOUT_OPTIONS,
      'elk.direction': direction,
    };

    const elkGraph = {
      id: 'root',
      layoutOptions,
      children: connectedPlacements.map((p) => ({
        id: p.placementId,
        width: p.width || 190,
        height: p.height || 76,
      })),
      edges: validBranches.map((b) => ({
        id: b.branchId,
        sources: [b.sourcePlacementId],
        targets: [b.targetPlacementId],
      })),
    };

    try {
      const laidOut = await elk.layout(elkGraph);

      if (laidOut.children && laidOut.children.length > 0) {
        let currentMinX = Infinity;
        let currentMaxY = -Infinity;

        for (const node of laidOut.children) {
          const nx = Math.round(node.x ?? 0);
          const ny = Math.round(node.y ?? 0);
          resultPositions[node.id] = { x: nx, y: ny };

          if (nx < currentMinX) {
            currentMinX = nx;
          }

          const nodeHeight = node.height ?? 76;
          if (ny + nodeHeight > currentMaxY) {
            currentMaxY = ny + nodeHeight;
          }
        }

        if (currentMinX !== Infinity) {
          minX = currentMinX;
        }
        if (currentMaxY !== -Infinity) {
          maxY = currentMaxY;
        }
      }
    } catch {
      // Graceful fallback if ELK fails unexpectedly: preserve existing positions
      for (const p of connectedPlacements) {
        resultPositions[p.placementId] = {
          x: Math.round(p.x ?? 0),
          y: Math.round(p.y ?? 0),
        };
      }
    }
  }

  // 2. Stage isolated (zero-degree) placements neatly below Tier 0
  if (isolatedPlacements.length > 0) {
    const rackY = maxY + 150;
    const rackSpacing = 220;

    isolatedPlacements.forEach((p, idx) => {
      resultPositions[p.placementId] = {
        x: minX + idx * rackSpacing,
        y: rackY,
      };
    });
  }

  return resultPositions;
}

/**
 * QualCount: Visual Multiplex Partnership Management System
 * Pure Quantitative 7-Metric Engine (src/engine/metrics.ts)
 * 
 * Derives honest, objective quantitative partnership indicators strictly from
 * live graph topology with zero subjective scoring (1-to-5 ratings) and zero
 * DOM/React/storage dependencies.
 */

import type { WorkspaceState, Branch, Placement } from '../types/schema';

// ---------------------------------------------------------------------------
// Metric Return Types
// ---------------------------------------------------------------------------

export interface FundingMetrics {
  securedPct: number;
  pendingPct: number;
  declinedCount: number;
  securedInr: number;
}

export interface DirectRelationshipMetrics {
  confirmedCount: number;
  pendingCount: number;
  declinedCount: number;
  confirmationRatePct: number;
}

export interface YellowBridgeMetrics {
  confirmedCount: number;
  pendingCount: number;
  declinedCount: number;
}

export interface OwnedConversionMetrics {
  referredNodeCount: number;
  convertedNodeCount: number;
  conversionRatePct: number;
}

export interface MultiThreadMetrics {
  doubleThreadCount: number;
  tripleThreadCount: number;
  quadPlusThreadCount: number;
  triplePlusNames: string[];
}

export interface TopAmplifierMetrics {
  entityId: string | null;
  entityName: string;
  directOutDegree: number;
  downstreamReachCount: number;
}

export interface BridgeConcentrationMetrics {
  bridgeEntityName: string;
  concentrationPct: number;
  unreachableCount: number;
}

export interface WorkspaceTopologyMetrics {
  funding: FundingMetrics;
  directRelationships: DirectRelationshipMetrics;
  yellowBridges: YellowBridgeMetrics;
  ownedConversions: OwnedConversionMetrics;
  multiThreadTargets: MultiThreadMetrics;
  topAmplifier: TopAmplifierMetrics;
  bridgeConcentration: BridgeConcentrationMetrics;
}

// ---------------------------------------------------------------------------
// Helper: Normalize Branches
// ---------------------------------------------------------------------------

function toBranchArray(branches: Record<string, Branch> | Branch[]): Branch[] {
  return Array.isArray(branches) ? branches : Object.values(branches);
}

// ---------------------------------------------------------------------------
// Metric 5 Helper: Node-level Confirmed Yellow In-Degree
// ---------------------------------------------------------------------------

/**
 * Computes confirmed yellow in-degree for a specific placement card.
 * In QualCount, multiple ticked yellow branches converging on a single target
 * indicate multi-thread endorsement / triangulation.
 */
export function getNodeYellowInDegree(
  placementId: string,
  branches: Record<string, Branch> | Branch[]
): number {
  const branchList = toBranchArray(branches);
  return branchList.filter(
    (b) =>
      b.type === 'yellow' &&
      b.status === 'tick' &&
      b.targetPlacementId === placementId
  ).length;
}

// ---------------------------------------------------------------------------
// Metric 6 Helper: Node-level Downstream BFS Reach
// ---------------------------------------------------------------------------

function bfsReachFromAdj(
  placementId: string,
  adj: Map<string, string[]>,
  rootPlacementId?: string
): number {
  const visited = new Set<string>();
  const queue: string[] = [];

  const neighbors = adj.get(placementId) || [];
  for (const next of neighbors) {
    if (next !== placementId && next !== rootPlacementId && !visited.has(next)) {
      visited.add(next);
      queue.push(next);
    }
  }

  while (queue.length > 0) {
    const current = queue.shift()!;
    const nextNeighbors = adj.get(current) || [];
    for (const next of nextNeighbors) {
      if (next !== placementId && next !== rootPlacementId && !visited.has(next)) {
        visited.add(next);
        queue.push(next);
      }
    }
  }

  return visited.size;
}

/**
 * Runs Breadth-First Search (BFS) along confirmed (ticked) yellow referral branches
 * originating from a given placement, discovering all unique downstream placements.
 * Excludes self and root NGO from the reach set.
 */
export function getNodeAmplifierReach(
  placementId: string,
  _placements: Record<string, Placement>,
  branches: Record<string, Branch> | Branch[],
  rootPlacementId?: string
): number {
  const branchList = toBranchArray(branches);

  // Build adjacency list for ticked yellow edges
  const adj = new Map<string, string[]>();
  for (const b of branchList) {
    if (b.type === 'yellow' && b.status === 'tick') {
      let list = adj.get(b.sourcePlacementId);
      if (!list) {
        list = [];
        adj.set(b.sourcePlacementId, list);
      }
      list.push(b.targetPlacementId);
    }
  }

  return bfsReachFromAdj(placementId, adj, rootPlacementId);
}

// ---------------------------------------------------------------------------
// Main Engine: Compute All 7 Quantitative Topology Metrics
// ---------------------------------------------------------------------------

/**
 * Pure calculation engine computing all seven quantitative partnership metrics
 * directly from live graph records in the active workbook.
 */
export function computeTopologyMetrics(
  state: WorkspaceState,
  activeWorkbookId?: string
): WorkspaceTopologyMetrics {
  const targetWorkbookId = activeWorkbookId ?? state.activeWorkbookId;
  const workbook = state.workbooks[targetWorkbookId];

  const placements = Object.values(state.placements).filter(
    (p) => p.workbookId === targetWorkbookId
  );
  const branches = Object.values(state.branches).filter(
    (b) => b.workbookId === targetWorkbookId
  );

  const rootPlacement = placements.find((p) => p.isRootNgo);
  const rootPlacementId = rootPlacement?.placementId;

  // 1. Single-pass branch evaluation for funding, white ties, yellow bridges, and topology indexing
  let securedPct = 0;
  let pendingPct = 0;
  let greenDeclinedCount = 0;

  let whiteConfirmedCount = 0;
  let whitePendingCount = 0;
  let whiteDeclinedCount = 0;

  let yellowConfirmedCount = 0;
  let yellowPendingCount = 0;
  let yellowDeclinedCount = 0;

  const yellowInDegreeMap = new Map<string, number>();
  const incomingPartnerYellowCount = new Map<string, number>();
  const directWhiteFromRoot = new Set<string>();
  const directYellowOutDegreeMap = new Map<string, number>();
  const yellowAdj = new Map<string, string[]>();

  for (const b of branches) {
    if (b.type === 'green') {
      if (b.status === 'tick') {
        securedPct += b.valuePct || 0;
      } else if (b.status === 'pending') {
        pendingPct += b.valuePct || 0;
      } else if (b.status === 'cross') {
        greenDeclinedCount += 1;
      }
    } else if (b.type === 'white') {
      if (rootPlacementId && b.sourcePlacementId === rootPlacementId) {
        if (b.status === 'tick') {
          whiteConfirmedCount += 1;
        } else if (b.status === 'pending') {
          whitePendingCount += 1;
        } else if (b.status === 'cross') {
          whiteDeclinedCount += 1;
        }
      }
      if (b.status === 'tick' && rootPlacementId && b.sourcePlacementId === rootPlacementId) {
        directWhiteFromRoot.add(b.targetPlacementId);
      }
    } else if (b.type === 'yellow') {
      if (b.status === 'tick') {
        yellowConfirmedCount += 1;
        yellowInDegreeMap.set(b.targetPlacementId, (yellowInDegreeMap.get(b.targetPlacementId) || 0) + 1);
        directYellowOutDegreeMap.set(b.sourcePlacementId, (directYellowOutDegreeMap.get(b.sourcePlacementId) || 0) + 1);
        if (!rootPlacementId || b.sourcePlacementId !== rootPlacementId) {
          incomingPartnerYellowCount.set(b.targetPlacementId, (incomingPartnerYellowCount.get(b.targetPlacementId) || 0) + 1);
        }
        let list = yellowAdj.get(b.sourcePlacementId);
        if (!list) {
          list = [];
          yellowAdj.set(b.sourcePlacementId, list);
        }
        list.push(b.targetPlacementId);
      } else if (b.status === 'pending') {
        yellowPendingCount += 1;
      } else if (b.status === 'cross') {
        yellowDeclinedCount += 1;
      }
    }
  }

  const targetBudgetInr = workbook?.targetBudgetInr ?? 0;
  const securedInr = (securedPct / 100) * targetBudgetInr;

  const funding: FundingMetrics = {
    securedPct,
    pendingPct,
    declinedCount: greenDeclinedCount,
    securedInr,
  };

  const decidedWhiteTies = whiteConfirmedCount + whiteDeclinedCount;
  const confirmationRatePct =
    decidedWhiteTies > 0 ? (whiteConfirmedCount / decidedWhiteTies) * 100 : 0;

  const directRelationships: DirectRelationshipMetrics = {
    confirmedCount: whiteConfirmedCount,
    pendingCount: whitePendingCount,
    declinedCount: whiteDeclinedCount,
    confirmationRatePct,
  };

  const yellowBridges: YellowBridgeMetrics = {
    confirmedCount: yellowConfirmedCount,
    pendingCount: yellowPendingCount,
    declinedCount: yellowDeclinedCount,
  };

  // 4. Owned Conversions
  // Measures conversion of borrowed bridge reach into owned direct ties.
  // Referred nodes: non-root placements that have incoming yellow referral branches from a partner (source !== root).
  // Converted nodes: referred nodes that now also hold a direct confirmed white tie from root NGO.
  const nonRootPlacements = placements.filter((p) => !p.isRootNgo);

  let referredNodeCount = 0;
  let convertedNodeCount = 0;

  for (const p of nonRootPlacements) {
    const incomingPartnerCount = incomingPartnerYellowCount.get(p.placementId) || 0;
    if (incomingPartnerCount > 0) {
      referredNodeCount += 1;
      if (directWhiteFromRoot.has(p.placementId)) {
        convertedNodeCount += 1;
      }
    }
  }

  const conversionRatePct =
    referredNodeCount > 0 ? (convertedNodeCount / referredNodeCount) * 100 : 0;

  const ownedConversions: OwnedConversionMetrics = {
    referredNodeCount,
    convertedNodeCount,
    conversionRatePct,
  };

  // 5. Multi-Thread Targets
  let doubleThreadCount = 0;
  let tripleThreadCount = 0;
  let quadPlusThreadCount = 0;
  const triplePlusNames: string[] = [];

  for (const p of nonRootPlacements) {
    const inDeg = yellowInDegreeMap.get(p.placementId) || 0;
    if (inDeg === 2) {
      doubleThreadCount += 1;
    } else if (inDeg === 3) {
      tripleThreadCount += 1;
    } else if (inDeg >= 4) {
      quadPlusThreadCount += 1;
    }

    if (inDeg >= 3) {
      const entity = state.entities[p.entityId];
      if (entity?.name) {
        triplePlusNames.push(entity.name);
      }
    }
  }

  const multiThreadTargets: MultiThreadMetrics = {
    doubleThreadCount,
    tripleThreadCount,
    quadPlusThreadCount,
    triplePlusNames,
  };

  // 6. Top Amplifier (BFS reach)
  let bestAmplifierPlacement: Placement | null = null;
  let bestReachCount = 0;
  let bestDirectOutDegree = 0;

  const placementsById = new Map<string, Placement>();
  for (const p of placements) {
    placementsById.set(p.placementId, p);
  }

  for (const p of nonRootPlacements) {
    const directOutDegree = directYellowOutDegreeMap.get(p.placementId) || 0;
    if (directOutDegree === 0) continue; // Skip leaf nodes with no yellow out-degree

    const reachCount = bfsReachFromAdj(
      p.placementId,
      yellowAdj,
      rootPlacementId
    );

    if (
      reachCount > bestReachCount ||
      (reachCount === bestReachCount && directOutDegree > bestDirectOutDegree)
    ) {
      bestReachCount = reachCount;
      bestDirectOutDegree = directOutDegree;
      bestAmplifierPlacement = p;
    }
  }

  let topAmplifier: TopAmplifierMetrics;
  if (bestAmplifierPlacement && (bestReachCount > 0 || bestDirectOutDegree > 0)) {
    const entity = state.entities[bestAmplifierPlacement.entityId];
    topAmplifier = {
      entityId: bestAmplifierPlacement.entityId,
      entityName: entity?.name || '',
      directOutDegree: bestDirectOutDegree,
      downstreamReachCount: bestReachCount,
    };
  } else {
    topAmplifier = {
      entityId: null,
      entityName: '',
      directOutDegree: 0,
      downstreamReachCount: 0,
    };
  }

  // 7. Bridge Concentration Risk (%)
  // Computes percentage of confirmed indirect downstream nodes (path length >= 2 from root)
  // that become unreachable if the highest-reach bridge node is removed.
  let bridgeConcentration: BridgeConcentrationMetrics = {
    bridgeEntityName: '',
    concentrationPct: 0,
    unreachableCount: 0,
  };

  if (rootPlacementId) {
    // 1. Find unique direct bridge nodes from root (Level 1)
    const directBridgePlacementIds = Array.from(
      new Set(
        branches
          .filter(
            (b) =>
              b.type === 'yellow' &&
              b.status === 'tick' &&
              b.sourcePlacementId === rootPlacementId
          )
          .map((b) => b.targetPlacementId)
      )
    );

    // 2. Compute R_total: all unique placements reachable via ticked yellow paths of length >= 2 from root
    // Level 0: rootPlacementId
    // Level 1: directBridgePlacementIds
    // Level >= 2: indirect placements reachable from Level 1
    const getReachableFrom = (
      startIds: string[],
      blockedId?: string
    ): Set<string> => {
      const reached = new Set<string>();
      const queue = [...startIds].filter((id) => id !== blockedId);
      const visited = new Set<string>(queue);

      while (queue.length > 0) {
        const curr = queue.shift()!;
        if (curr === blockedId) continue;
        const neighbors = yellowAdj.get(curr) || [];
        for (const n of neighbors) {
          if (n !== rootPlacementId && n !== blockedId) {
            reached.add(n);
            if (!visited.has(n)) {
              visited.add(n);
              queue.push(n);
            }
          }
        }
      }

      // Filter out level 1 direct bridges from indirect reach set
      for (const bId of directBridgePlacementIds) {
        reached.delete(bId);
      }
      return reached;
    };

    const rTotal = getReachableFrom(directBridgePlacementIds);

    if (rTotal.size > 0 && directBridgePlacementIds.length > 0) {
      // Find the highest-reach bridge node b among direct bridges,
      // breaking any reach ties by lost reach count
      let worstBridgeId = directBridgePlacementIds[0];
      let maxReach = -1;
      let maxLostCount = -1;

      for (const bId of directBridgePlacementIds) {
        const reach = getNodeAmplifierReach(
          bId,
          state.placements,
          branches,
          rootPlacementId
        );
        const remainingBridgeIds = directBridgePlacementIds.filter(
          (id) => id !== bId
        );
        const rWithoutB = getReachableFrom(remainingBridgeIds, bId);
        const lostCount = rTotal.size - rWithoutB.size;

        if (
          reach > maxReach ||
          (reach === maxReach && lostCount > maxLostCount)
        ) {
          maxReach = reach;
          maxLostCount = lostCount;
          worstBridgeId = bId;
        }
      }

      const bridgePlacement = state.placements[worstBridgeId];
      const bridgeEntity = bridgePlacement
        ? state.entities[bridgePlacement.entityId]
        : null;

      const concentrationPct = (maxLostCount / rTotal.size) * 100;

      bridgeConcentration = {
        bridgeEntityName: bridgeEntity?.name || '',
        concentrationPct,
        unreachableCount: maxLostCount,
      };
    }
  }

  return {
    funding,
    directRelationships,
    yellowBridges,
    ownedConversions,
    multiThreadTargets,
    topAmplifier,
    bridgeConcentration,
  };
}

/**
 * QualCount: Visual Multiplex Partnership Management System
 * Pure Local Rectangular Anti-Overlap Engine (src/engine/overlap.ts)
 * 
 * Detects rectangular bounding-box collisions with a 24px safety margin.
 * When the user drags and drops a node card, the dropped card remains strictly
 * anchored at its exact coordinates, while only colliding neighbor cards are
 * nudged apart along the axis of minimum penetration.
 * 
 * Pure TypeScript (zero DOM/React/storage dependencies).
 */

import type { Placement } from '../types/schema';

// ---------------------------------------------------------------------------
// Interfaces
// ---------------------------------------------------------------------------

export interface BoundingBox {
  id: string;
  x: number;
  y: number;
  width: number;
  height: number;
  isFixed?: boolean;
}

export interface CollisionResolutionResult {
  positions: Record<string, { x: number; y: number }>;
  movedNodeIds: string[];
}

// ---------------------------------------------------------------------------
// AABB Collision Detection with Margin
// ---------------------------------------------------------------------------

/**
 * Checks whether two rectangular bounding boxes collide, enforcing a minimum
 * clearance safety margin on all sides.
 * 
 * @param boxA First bounding box
 * @param boxB Second bounding box
 * @param margin Required clearance distance between boxes (default 24px)
 */
export function checkAABBCollision(
  boxA: BoundingBox,
  boxB: BoundingBox,
  margin: number = 24
): { collides: boolean; overlapX: number; overlapY: number } {
  const centerAX = boxA.x + boxA.width / 2;
  const centerAY = boxA.y + boxA.height / 2;
  const centerBX = boxB.x + boxB.width / 2;
  const centerBY = boxB.y + boxB.height / 2;

  const halfWidthA = boxA.width / 2;
  const halfWidthB = boxB.width / 2;
  const halfHeightA = boxA.height / 2;
  const halfHeightB = boxB.height / 2;

  const dx = Math.abs(centerBX - centerAX);
  const dy = Math.abs(centerBY - centerAY);

  const reqDistanceX = halfWidthA + halfWidthB + margin;
  const reqDistanceY = halfHeightA + halfHeightB + margin;

  const overlapX = reqDistanceX - dx;
  const overlapY = reqDistanceY - dy;

  if (overlapX > 0 && overlapY > 0) {
    return {
      collides: true,
      overlapX,
      overlapY,
    };
  }

  return {
    collides: false,
    overlapX: Math.max(0, overlapX),
    overlapY: Math.max(0, overlapY),
  };
}

// ---------------------------------------------------------------------------
// Iterative Local Anti-Overlap Resolution
// ---------------------------------------------------------------------------

/**
 * Iteratively resolves bounding-box overlaps among cards.
 * If anchoredPlacementId is specified, that card remains strictly fixed in place
 * (its x and y coordinates are never modified), and only colliding neighbors are shifted.
 * Uninvolved cards stay completely stationary.
 */
export function resolveLocalCollisions(
  placements: Record<string, Placement>,
  anchoredPlacementId?: string,
  margin: number = 24,
  maxIterations: number = 50
): CollisionResolutionResult {
  const boxes: Map<string, BoundingBox> = new Map();

  for (const [id, p] of Object.entries(placements)) {
    boxes.set(id, {
      id,
      x: p.x ?? 0,
      y: p.y ?? 0,
      width: p.width || 190,
      height: p.height || 76,
      isFixed: id === anchoredPlacementId,
    });
  }

  const boxList = Array.from(boxes.values());

  for (let iter = 0; iter < maxIterations; iter++) {
    let hasCollision = false;
    // Sweep-and-prune spatial optimization: sort by X axis to skip distant non-overlapping pairs
    boxList.sort((a, b) => a.x - b.x);

    for (let i = 0; i < boxList.length; i++) {
      const boxA = boxList[i];
      const maxReachX = boxA.x + boxA.width + margin;

      for (let j = i + 1; j < boxList.length; j++) {
        const boxB = boxList[j];
        if (boxB.x > maxReachX) {
          // Since boxList is sorted by x, no subsequent box can overlap with boxA in x
          break;
        }

        const { collides, overlapX, overlapY } = checkAABBCollision(
          boxA,
          boxB,
          margin
        );

        if (!collides) {
          continue;
        }

        hasCollision = true;

        const centerAX = boxA.x + boxA.width / 2;
        const centerAY = boxA.y + boxA.height / 2;
        const centerBX = boxB.x + boxB.width / 2;
        const centerBY = boxB.y + boxB.height / 2;

        // Displace along axis of minimum penetration
        if (overlapX < overlapY) {
          // Horizontal shift
          const dir = centerBX >= centerAX ? 1 : -1;

          if (boxA.isFixed && !boxB.isFixed) {
            boxB.x += dir * overlapX;
          } else if (boxB.isFixed && !boxA.isFixed) {
            boxA.x -= dir * overlapX;
          } else if (!boxA.isFixed && !boxB.isFixed) {
            boxA.x -= dir * (overlapX / 2);
            boxB.x += dir * (overlapX / 2);
          }
        } else {
          // Vertical shift
          const dir = centerBY >= centerAY ? 1 : -1;

          if (boxA.isFixed && !boxB.isFixed) {
            boxB.y += dir * overlapY;
          } else if (boxB.isFixed && !boxA.isFixed) {
            boxA.y -= dir * overlapY;
          } else if (!boxA.isFixed && !boxB.isFixed) {
            boxA.y -= dir * (overlapY / 2);
            boxB.y += dir * (overlapY / 2);
          }
        }
      }
    }

    if (!hasCollision) {
      break;
    }
  }

  const positions: Record<string, { x: number; y: number }> = {};
  const movedNodeIds: string[] = [];

  for (const [id, box] of boxes.entries()) {
    const finalX = Math.round(box.x);
    const finalY = Math.round(box.y);
    positions[id] = { x: finalX, y: finalY };

    const orig = placements[id];
    if (orig && (finalX !== Math.round(orig.x) || finalY !== Math.round(orig.y))) {
      movedNodeIds.push(id);
    }
  }

  return {
    positions,
    movedNodeIds,
  };
}

/**
 * QualCount: Visual Multiplex Partnership Management System
 * Pure Parallel Bezier Curve Offset Engine (src/engine/parallelEdges.ts)
 * 
 * Computes lateral Bezier curve offsets for concurrent multiplex branches
 * connecting the same pair of nodes (e.g. Funding Green + Relationship White +
 * Bridge Yellow) so lines, mid-line M% pills (t = 0.5), and end-of-line
 * Tick/Cross buttons (t = 0.8) never stack or collide.
 * 
 * Pure TypeScript (zero DOM/React/storage dependencies).
 */

import type { Branch } from '../types/schema';

// ---------------------------------------------------------------------------
// Interfaces
// ---------------------------------------------------------------------------

export interface EdgeEndpoint {
  x: number;
  y: number;
}

export interface ParallelBranchGeometry {
  path: string;
  labelX: number;
  labelY: number;
  buttonX: number;
  buttonY: number;
  offsetDistance: number;
}

// ---------------------------------------------------------------------------
// Branch Grouping
// ---------------------------------------------------------------------------

/**
 * Groups branches connecting the same pair of placements regardless of direction,
 * using a canonical undirected pair key.
 */
export function groupParallelBranches(branches: Branch[]): Map<string, Branch[]> {
  const groups = new Map<string, Branch[]>();

  for (const branch of branches) {
    const p1 = branch.sourcePlacementId;
    const p2 = branch.targetPlacementId;
    const key = p1 < p2 ? `${p1}---${p2}` : `${p2}---${p1}`;

    const list = groups.get(key);
    if (list) {
      list.push(branch);
    } else {
      groups.set(key, [branch]);
    }
  }

  return groups;
}

// ---------------------------------------------------------------------------
// Cubic Bezier Math Helper
// ---------------------------------------------------------------------------

/**
 * Evaluates a 1D cubic Bezier coordinate at parameter t in [0, 1].
 * B(t) = (1-t)^3 * p0 + 3(1-t)^2 * t * p1 + 3(1-t) * t^2 * p2 + t^3 * p3
 */
export function evaluateCubicBezier1D(
  p0: number,
  p1: number,
  p2: number,
  p3: number,
  t: number
): number {
  const s = 1 - t;
  return (
    s * s * s * p0 +
    3 * s * s * t * p1 +
    3 * s * t * t * p2 +
    t * t * t * p3
  );
}

// ---------------------------------------------------------------------------
// Lateral Bezier Curve Computation
// ---------------------------------------------------------------------------

/**
 * Computes symmetric lateral Bezier curve offset and exact coordinates for:
 * - Mid-line M% pill (t = 0.5)
 * - End-of-line Tick / Cross buttons (t = 0.8)
 * 
 * @param source Starting endpoint (x, y)
 * @param target Ending endpoint (x, y)
 * @param index 0-based index of this branch within its parallel group
 * @param total Total number of parallel branches connecting this pair
 * @param spacing Lateral pixel clearance between parallel branches (default 36px)
 * @param isReverse Optional boolean indicating if this branch runs in reverse of canonical pair direction
 * @param buttonT Optional parameter t for positioning action buttons (default 0.8, or ~0.88-0.92 under target node)
 */
export function computeParallelBezierCurve(
  source: EdgeEndpoint,
  target: EdgeEndpoint,
  index: number,
  total: number,
  spacing: number = 36,
  isReverse?: boolean,
  buttonT: number = 0.8
): ParallelBranchGeometry {
  // Symmetric displacement offset: e.g. for total = 2, offsets are -18 and +18.
  // For total = 1, offset is strictly 0.
  const d = total <= 1 ? 0 : (index - (total - 1) / 2) * spacing;

  const dx = target.x - source.x;
  const dy = target.y - source.y;
  const len = Math.sqrt(dx * dx + dy * dy);

  // If endpoints are virtually identical (degenerate edge), return zero-length line
  if (len < 1) {
    return {
      path: `M ${source.x} ${source.y} L ${target.x} ${target.y}`,
      labelX: source.x,
      labelY: source.y,
      buttonX: target.x,
      buttonY: target.y,
      offsetDistance: 0,
    };
  }

  // Canonical ordering for consistent lateral offset direction in world space:
  // In bottom-to-top layout, canonical direction is bottom (larger y) to top (smaller y).
  // If endpoints have identical y, canonical direction is left (smaller x) to right (larger x).
  const isReversed =
    isReverse !== undefined
      ? isReverse
      : source.y < target.y || (source.y === target.y && source.x > target.x);

  // Invert displacement offset along local normal when branch is reversed,
  // preventing opposing parallel branches from curving into the same lane.
  const effectiveD = isReversed ? -d : d;

  // Unit normal vector perpendicular to direction vector (dx, dy)
  const nx = -dy / len;
  const ny = dx / len;

  // Control points: baseline vertical curvature with lateral normal offset
  const cp1x = source.x + nx * effectiveD;
  const cp1y = source.y + dy * 0.35 + ny * effectiveD;

  const cp2x = target.x + nx * effectiveD;
  const cp2y = target.y - dy * 0.35 + ny * effectiveD;

  const path = `M ${source.x} ${source.y} C ${cp1x} ${cp1y}, ${cp2x} ${cp2y}, ${target.x} ${target.y}`;

  // Evaluate exact coordinates at t = 0.5 (midpoint) and t = buttonT (near target / under node)
  const labelX = evaluateCubicBezier1D(source.x, cp1x, cp2x, target.x, 0.5);
  const labelY = evaluateCubicBezier1D(source.y, cp1y, cp2y, target.y, 0.5);

  const buttonX = evaluateCubicBezier1D(source.x, cp1x, cp2x, target.x, buttonT);
  const buttonY = evaluateCubicBezier1D(source.y, cp1y, cp2y, target.y, buttonT);

  return {
    path,
    labelX,
    labelY,
    buttonX,
    buttonY,
    offsetDistance: d,
  };
}

/**
 * QualCount: Visual Multiplex Partnership Management System
 * Pure Deterministic Structural Risk Engine (src/engine/risk.ts)
 * 
 * Computes Layer 1 structural risk across 6 explicit parameters with pinpointed
 * offending placement and branch IDs.
 * Zero machine learning, zero black boxes, zero DOM/React/storage dependencies.
 * 
 * Parameters:
 * R1: Single-Bridge Concentration Risk (Freeman Articulation Loss)
 * R2: Unowned Dependency Exposure (Ostrom Durability Risk)
 * R3: Funding Concentration & Runway Gap
 * R4: Public Choice Apathy Risk (Olson Cold-Pitch Risk)
 * R5: Decision-Cost Drag & Stale Pipeline (Buchanan Decision Sinks)
 * R6: Rejection Cluster Signal (Contagion/Decline Clusters)
 */

import type {
  Entity,
  RiskSeverity,
  WorkspaceState,
} from '../types/schema';
import type { WorkbookLike } from './utility';

export interface RiskParameterResult {
  id: 'R1' | 'R2' | 'R3' | 'R4' | 'R5' | 'R6';
  name: string;
  score: number;
  scoreFormatted: string;
  severity: RiskSeverity;
  thresholdDescription: string;
  plainCommentary: string;
  offendingPlacementIds: string[];
  offendingBranchIds: string[];
}

export interface StructuralRiskReport {
  aggregateTier: RiskSeverity;
  assessedAt: string;
  parameters: Record<'R1' | 'R2' | 'R3' | 'R4' | 'R5' | 'R6', RiskParameterResult>;
  allOffendingPlacementIds: string[];
  allOffendingBranchIds: string[];
}

/**
 * Computes the 6-parameter deterministic Layer 1 structural risk report.
 */
export function computeStructuralRiskReport(
  workbook: WorkbookLike,
  entities: Record<string, Entity>,
  referenceTimeMs: number = Date.now()
): StructuralRiskReport {
  const placementsList = Object.values(workbook.placements);
  const branchesList = Object.values(workbook.branches);
  const rootPlacement = placementsList.find((p) => p.isRootNgo);
  const rootPlacementId = rootPlacement?.placementId || '';

  // ---------------------------------------------------------------------------
  // Parameter R1: Single-Bridge Concentration (Freeman Articulation Loss)
  // ---------------------------------------------------------------------------
  // Build confirmed yellow graph adjacency
  const yellowAdj: Record<string, string[]> = {};
  for (const b of branchesList) {
    if (b.type === 'yellow' && b.status === 'tick') {
      if (!yellowAdj[b.sourcePlacementId]) yellowAdj[b.sourcePlacementId] = [];
      yellowAdj[b.sourcePlacementId].push(b.targetPlacementId);
    }
  }

  // Find all nodes reachable at distance >= 2 from Root NGO via ticked yellow paths
  // Distance 1 = direct yellow from root
  const distFromRoot: Record<string, number> = {};
  if (rootPlacementId) {
    const q: Array<{ id: string; dist: number }> = [{ id: rootPlacementId, dist: 0 }];
    distFromRoot[rootPlacementId] = 0;
    while (q.length > 0) {
      const { id, dist } = q.shift()!;
      for (const next of yellowAdj[id] || []) {
        if (distFromRoot[next] === undefined) {
          distFromRoot[next] = dist + 1;
          q.push({ id: next, dist: dist + 1 });
        }
      }
    }
  }

  const indirectNodes = Object.keys(distFromRoot).filter(
    (id) => id !== rootPlacementId && distFromRoot[id] >= 2
  );

  let maxLossPct = 0;
  let topBridgeId = '';
  const r1OffendingPlacements: string[] = [];
  const r1OffendingBranches: string[] = [];

  if (indirectNodes.length > 0) {
    // Non-root intermediate nodes that could act as bridges
    const candidateBridges = Object.keys(distFromRoot).filter(
      (id) => id !== rootPlacementId && (yellowAdj[id] || []).length > 0
    );

    for (const bridgeId of candidateBridges) {
      // Simulate removing bridgeId: how many indirectNodes become unreachable from Root?
      const simVisited = new Set<string>();
      const simQ: string[] = [rootPlacementId];
      simVisited.add(rootPlacementId);

      while (simQ.length > 0) {
        const curr = simQ.shift()!;
        for (const next of yellowAdj[curr] || []) {
          if (next !== bridgeId && !simVisited.has(next)) {
            simVisited.add(next);
            simQ.push(next);
          }
        }
      }

      const evalNodes = indirectNodes.filter((id) => id !== bridgeId);
      const lostCount = evalNodes.filter((id) => !simVisited.has(id)).length;
      const lossPct = evalNodes.length > 0 ? (lostCount / evalNodes.length) * 100 : 0;
      if (lossPct > maxLossPct) {
        maxLossPct = lossPct;
        topBridgeId = bridgeId;
      }
    }
  }

  let r1Severity: RiskSeverity = 'low';
  if (maxLossPct > 70) r1Severity = 'critical';
  else if (maxLossPct >= 50) r1Severity = 'elevated';
  else if (maxLossPct >= 35) r1Severity = 'moderate';

  if (topBridgeId && r1Severity !== 'low') {
    r1OffendingPlacements.push(topBridgeId);
    const bridgeBranches = branchesList
      .filter(
        (b) =>
          (b.sourcePlacementId === topBridgeId || b.targetPlacementId === topBridgeId) &&
          b.type === 'yellow' &&
          b.status === 'tick'
      )
      .map((b) => b.branchId);
    r1OffendingBranches.push(...bridgeBranches);
  }

  const bridgeName = topBridgeId ? entities[workbook.placements[topBridgeId]?.entityId]?.name || topBridgeId : 'None';
  const r1: RiskParameterResult = {
    id: 'R1',
    name: 'Single-Bridge Concentration',
    score: Number(maxLossPct.toFixed(1)),
    scoreFormatted: `${maxLossPct.toFixed(1)}%`,
    severity: r1Severity,
    thresholdDescription: 'Low < 35% | Mod 35-50% | Elev 50-70% | Crit > 70%',
    plainCommentary:
      maxLossPct === 0
        ? 'No articulation bridge bottleneck detected. Network pathways are either direct or diversified.'
        : `${maxLossPct.toFixed(1)}% of indirect downstream network depends on a single bridge (${bridgeName}).`,
    offendingPlacementIds: r1OffendingPlacements,
    offendingBranchIds: r1OffendingBranches,
  };

  // ---------------------------------------------------------------------------
  // Parameter R2: Unowned Dependency Exposure (Ostrom Durability Risk)
  // ---------------------------------------------------------------------------
  // Yellow-referred nodes: non-root nodes receiving at least one confirmed yellow branch
  const yellowReferredNodes = new Set<string>();
  for (const b of branchesList) {
    if (b.type === 'yellow' && b.status === 'tick') {
      const tgt = workbook.placements[b.targetPlacementId];
      if (tgt && !tgt.isRootNgo) {
        yellowReferredNodes.add(b.targetPlacementId);
      }
    }
  }

  const unownedNodes = Array.from(yellowReferredNodes).filter((targetId) => {
    // Check if Root NGO has a direct ticked white branch to targetId
    const hasWhiteTick = branchesList.some(
      (b) =>
        b.sourcePlacementId === rootPlacementId &&
        b.targetPlacementId === targetId &&
        b.type === 'white' &&
        b.status === 'tick'
    );
    return !hasWhiteTick;
  });

  const r2Score =
    yellowReferredNodes.size > 0 ? (unownedNodes.length / yellowReferredNodes.size) * 100 : 0;

  let r2Severity: RiskSeverity = 'low';
  if (r2Score > 75) r2Severity = 'critical';
  else if (r2Score >= 50) r2Severity = 'elevated';
  else if (r2Score >= 30) r2Severity = 'moderate';

  const r2OffendingPlacements = r2Severity !== 'low' ? unownedNodes : [];
  const r2: RiskParameterResult = {
    id: 'R2',
    name: 'Unowned Dependency Exposure',
    score: Number(r2Score.toFixed(1)),
    scoreFormatted: `${r2Score.toFixed(1)}%`,
    severity: r2Severity,
    thresholdDescription: 'Low < 30% | Mod 30-50% | Elev 50-75% | Crit > 75%',
    plainCommentary:
      yellowReferredNodes.size === 0
        ? 'No referred nodes in workspace.'
        : `${unownedNodes.length} of ${yellowReferredNodes.size} referred partners (${r2Score.toFixed(1)}%) lack a direct confirmed working relationship with the lead NGO.`,
    offendingPlacementIds: r2OffendingPlacements,
    offendingBranchIds: [],
  };

  // ---------------------------------------------------------------------------
  // Parameter R3: Funding Concentration & Runway Gap
  // ---------------------------------------------------------------------------
  const greenBranches = branchesList.filter((b) => b.type === 'green');
  const securedCashPct = greenBranches
    .filter((b) => b.status === 'tick')
    .reduce((sum, b) => sum + (b.valuePct || 0), 0);
  const pendingCashPct = greenBranches
    .filter((b) => b.status === 'pending')
    .reduce((sum, b) => sum + (b.valuePct || 0), 0);

  // Group secured funding by donor placement
  const donorSecured: Record<string, number> = {};
  for (const b of greenBranches) {
    if (b.status === 'tick' && b.valuePct) {
      donorSecured[b.targetPlacementId] = (donorSecured[b.targetPlacementId] || 0) + b.valuePct;
    }
  }

  let topDonorPlacementId = '';
  let topDonorSecuredPct = 0;
  for (const [plcId, val] of Object.entries(donorSecured)) {
    if (val > topDonorSecuredPct) {
      topDonorSecuredPct = val;
      topDonorPlacementId = plcId;
    }
  }

  const topDonorShareOfSecured =
    securedCashPct > 0 ? (topDonorSecuredPct / securedCashPct) * 100 : 0;
  const combinedFunding = securedCashPct + pendingCashPct;

  let r3Severity: RiskSeverity = 'low';
  if (topDonorShareOfSecured > 65 || combinedFunding < 50) {
    r3Severity = 'critical';
  } else if (topDonorShareOfSecured > 50) {
    r3Severity = 'elevated';
  } else if (topDonorShareOfSecured > 35 || combinedFunding < 75) {
    r3Severity = 'moderate';
  }

  const r3OffendingPlacements: string[] = [];
  const r3OffendingBranches: string[] = [];
  if (topDonorPlacementId && (r3Severity === 'elevated' || r3Severity === 'critical')) {
    r3OffendingPlacements.push(topDonorPlacementId);
    const donorBranches = greenBranches
      .filter((b) => b.targetPlacementId === topDonorPlacementId && b.status === 'tick')
      .map((b) => b.branchId);
    r3OffendingBranches.push(...donorBranches);
  }

  const r3: RiskParameterResult = {
    id: 'R3',
    name: 'Funding Concentration & Runway Gap',
    score: Number(topDonorShareOfSecured.toFixed(1)),
    scoreFormatted: `${topDonorShareOfSecured.toFixed(1)}% / ${combinedFunding.toFixed(1)}%`,
    severity: r3Severity,
    thresholdDescription: 'Crit: single donor >65% OR combined <50% | Elev: single >50%',
    plainCommentary: `Top donor accounts for ${topDonorShareOfSecured.toFixed(1)}% of secured cash. Combined pipeline covers ${combinedFunding.toFixed(1)}% of budget.`,
    offendingPlacementIds: r3OffendingPlacements,
    offendingBranchIds: r3OffendingBranches,
  };

  // ---------------------------------------------------------------------------
  // Parameter R4: Public Choice Apathy Risk (Olson Cold-Pitch Risk)
  // ---------------------------------------------------------------------------
  const nonRootPlacements = placementsList.filter((p) => !p.isRootNgo);
  // Candidates: active pending non-root prospects without confirmed commitment
  const pendingPartners = nonRootPlacements.filter((p) => {
    const hasTick = branchesList.some(
      (b) => b.targetPlacementId === p.placementId && b.status === 'tick'
    );
    if (hasTick) return false;
    const hasPending = branchesList.some(
      (b) => b.targetPlacementId === p.placementId && b.status === 'pending'
    );
    const hasAnyIncoming = branchesList.some(
      (b) => b.targetPlacementId === p.placementId
    );
    return hasAnyIncoming ? hasPending : true;
  });

  const apathyPartners = pendingPartners.filter((p) => {
    const yellowIn = branchesList.filter(
      (b) => b.targetPlacementId === p.placementId && b.type === 'yellow' && b.status === 'tick'
    ).length;
    const incentivesCount = p.selectiveIncentives?.length ?? 0;
    return yellowIn === 0 && incentivesCount === 0;
  });

  const denominator = pendingPartners.length > 0 ? pendingPartners.length : nonRootPlacements.length;
  const r4Score = denominator > 0 ? (apathyPartners.length / denominator) * 100 : 0;

  let r4Severity: RiskSeverity = 'low';
  if (r4Score > 60) r4Severity = 'critical';
  else if (r4Score >= 40) r4Severity = 'elevated';
  else if (r4Score >= 20) r4Severity = 'moderate';

  const r4OffendingPlacements = r4Severity !== 'low' ? apathyPartners.map((p) => p.placementId) : [];
  const r4: RiskParameterResult = {
    id: 'R4',
    name: 'Public Choice Apathy Risk',
    score: Number(r4Score.toFixed(1)),
    scoreFormatted: `${r4Score.toFixed(1)}%`,
    severity: r4Severity,
    thresholdDescription: 'Low < 20% | Mod 20-40% | Elev 40-60% | Crit > 60%',
    plainCommentary:
      apathyPartners.length === 0
        ? 'No apathy risk detected. All pending prospects possess either selective incentives or institutional referrals.'
        : `${apathyPartners.length} unconfirmed prospects lack both selective incentives and referrals (high probability of rational apathy).`,
    offendingPlacementIds: r4OffendingPlacements,
    offendingBranchIds: [],
  };

  // ---------------------------------------------------------------------------
  // Parameter R5: Decision-Cost Drag & Stale Pipeline
  // ---------------------------------------------------------------------------
  const FOURTEEN_DAYS_MS = 14 * 24 * 60 * 60 * 1000;
  const staleBranches = branchesList.filter((b) => {
    if (b.status !== 'pending') return false;
    const createdMs = b.createdAt ? new Date(b.createdAt).getTime() : (b.updatedAt ? new Date(b.updatedAt).getTime() : 0);
    return createdMs > 0 && referenceTimeMs - createdMs > FOURTEEN_DAYS_MS;
  });

  // Partners with outreachAttempts >= 4 and zero ticks
  const highFrictionPartners = nonRootPlacements.filter((p) => {
    const touches = p.outreachAttempts ?? 1;
    if (touches < 4) return false;
    const hasTick = branchesList.some(
      (b) => (b.targetPlacementId === p.placementId || b.sourcePlacementId === p.placementId) && b.status === 'tick'
    );
    return !hasTick;
  });

  const r5Score = staleBranches.length + highFrictionPartners.length;

  let r5Severity: RiskSeverity = 'low';
  if (r5Score >= 6) r5Severity = 'critical';
  else if (r5Score >= 3) r5Severity = 'elevated';
  else if (r5Score >= 1) r5Severity = 'moderate';

  const r5OffendingPlacements = r5Severity !== 'low' ? highFrictionPartners.map((p) => p.placementId) : [];
  const r5OffendingBranches = r5Severity !== 'low' ? staleBranches.map((b) => b.branchId) : [];

  const r5: RiskParameterResult = {
    id: 'R5',
    name: 'Decision-Cost Drag & Stale Pipeline',
    score: r5Score,
    scoreFormatted: `${r5Score} issues`,
    severity: r5Severity,
    thresholdDescription: 'Low = 0 | Mod = 1-2 | Elev = 3-5 | Crit >= 6',
    plainCommentary:
      r5Score === 0
        ? 'Pipeline is fresh and active. No stale branches or decision-sink partners.'
        : `${staleBranches.length} branches unresolved >14 days; ${highFrictionPartners.length} partners at >=4 touches with 0 commitments.`,
    offendingPlacementIds: r5OffendingPlacements,
    offendingBranchIds: r5OffendingBranches,
  };

  // ---------------------------------------------------------------------------
  // Parameter R6: Rejection Cluster Signal
  // ---------------------------------------------------------------------------
  const totalTicks = branchesList.filter((b) => b.status === 'tick').length;
  const totalCrosses = branchesList.filter((b) => b.status === 'cross').length;
  const totalResolved = totalTicks + totalCrosses;
  const overallRejectionRate = totalResolved > 0 ? (totalCrosses / totalResolved) * 100 : 0;

  // Check category-specific clusters (>= 3 declines & > 60% failure rate)
  const categoryDeclines: Record<string, { tick: number; cross: number }> = {};
  for (const b of branchesList) {
    if (b.status === 'tick' || b.status === 'cross') {
      const tgt = workbook.placements[b.targetPlacementId];
      if (tgt) {
        const cat = entities[tgt.entityId]?.category || 'other';
        if (!categoryDeclines[cat]) categoryDeclines[cat] = { tick: 0, cross: 0 };
        if (b.status === 'tick') categoryDeclines[cat].tick++;
        if (b.status === 'cross') categoryDeclines[cat].cross++;
      }
    }
  }

  let hasCategoryCluster = false;
  let clusteredCategory = '';
  for (const [cat, counts] of Object.entries(categoryDeclines)) {
    const total = counts.tick + counts.cross;
    if (counts.cross >= 3 && counts.cross / total > 0.60) {
      hasCategoryCluster = true;
      clusteredCategory = cat;
      break;
    }
  }

  let r6Severity: RiskSeverity = 'low';
  if (overallRejectionRate > 65 || hasCategoryCluster) {
    r6Severity = 'critical';
  } else if (overallRejectionRate >= 45) {
    r6Severity = 'elevated';
  } else if (overallRejectionRate >= 25) {
    r6Severity = 'moderate';
  }

  const r6OffendingBranches = branchesList.filter((b) => b.status === 'cross').map((b) => b.branchId);
  const r6OffendingPlacements = branchesList
    .filter((b) => b.status === 'cross')
    .map((b) => b.targetPlacementId);

  const r6: RiskParameterResult = {
    id: 'R6',
    name: 'Rejection Cluster Signal',
    score: Number(overallRejectionRate.toFixed(1)),
    scoreFormatted: `${overallRejectionRate.toFixed(1)}%`,
    severity: r6Severity,
    thresholdDescription: 'Low < 25% | Mod 25-45% | Elev 45-65% | Crit > 65%',
    plainCommentary: hasCategoryCluster
      ? `Rejection cluster detected in '${clusteredCategory}' sector (>=3 declines, >60% decline rate).`
      : `${totalCrosses} total declines out of ${totalResolved} resolved branches (${overallRejectionRate.toFixed(1)}% decline rate).`,
    offendingPlacementIds: r6Severity !== 'low' ? Array.from(new Set(r6OffendingPlacements)) : [],
    offendingBranchIds: r6Severity !== 'low' ? r6OffendingBranches : [],
  };

  // ---------------------------------------------------------------------------
  // Aggregate Structural Risk Tier
  // ---------------------------------------------------------------------------
  const params = { R1: r1, R2: r2, R3: r3, R4: r4, R5: r5, R6: r6 };
  const severities = Object.values(params).map((p) => p.severity);
  const criticalCount = severities.filter((s) => s === 'critical').length;
  const elevatedCount = severities.filter((s) => s === 'elevated').length;
  const moderateCount = severities.filter((s) => s === 'moderate').length;

  let aggregateTier: RiskSeverity = 'low';
  if (criticalCount >= 1 || elevatedCount >= 3) {
    aggregateTier = 'critical';
  } else if (elevatedCount >= 1 || moderateCount >= 3) {
    aggregateTier = 'elevated';
  } else if (moderateCount >= 1) {
    aggregateTier = 'moderate';
  }

  // Pinpoint all unique offending placement and branch IDs
  const allOffendingPlacements = Array.from(
    new Set(Object.values(params).flatMap((p) => p.offendingPlacementIds))
  );
  const allOffendingBranches = Array.from(
    new Set(Object.values(params).flatMap((p) => p.offendingBranchIds))
  );

  return {
    aggregateTier,
    assessedAt: new Date(referenceTimeMs).toISOString(),
    parameters: params,
    allOffendingPlacementIds: allOffendingPlacements,
    allOffendingBranchIds: allOffendingBranches,
  };
}

/**
 * Convenient helper to assess a workbook's structural risk report
 * directly from workspace state and workbookId.
 */
export function assessWorkbookStructuralRisk(
  workspace: WorkspaceState,
  workbookId: string,
  referenceTimeMs?: number
): StructuralRiskReport {
  const wb = workspace.workbooks[workbookId];
  const wbContext: WorkbookLike = {
    ...workspace,
    activeWorkbookId: workbookId,
    utilityWeights: wb?.utilityWeights,
    targetBudgetInr: wb?.targetBudgetInr,
  };
  return computeStructuralRiskReport(wbContext, workspace.entities, referenceTimeMs);
}

/**
 * QualCount: Visual Multiplex Partnership Management System
 * Pure Public Choice Theory Utility Engine (src/engine/utility.ts)
 * 
 * Computes objective, ratio-scale microeconomic utility metrics strictly from
 * live multiplex network topology without subjective 1-to-5 surveys.
 * 
 * Rooted in:
 * - Buchanan & Tullock (1962): Decision-making costs & touch efficiency (eta_i)
 * - Olson (1965): Selective incentives (I_i) & collective action screening
 * - Niskanen (1971): Bureaucratic inertia & screening cost reduction
 * - Ostrom (1990): Credible commitments, co-ownership depth (O_i) & owned conversion (V_i)
 * - Centola & Macy (2007): Social proof via multi-thread referrals (S_i, C_i)
 * 
 * Engine Isolation: Pure TypeScript. Zero imports from external DOM or storage runtimes.
 */

import type {
  Placement,
  Branch,
  Entity,
  UtilityStrategyWeights,
  CoOwnershipChecklist,
  WorkspaceState,
} from '../types/schema';
import { DEFAULT_UTILITY_WEIGHTS } from '../types/schema';

export interface PartnerUtilityDecomposition {
  R: number; // Direct commitment [0, 1]
  A: number; // Ecosystem amplification reach [0, 1]
  V: number; // Owned relationship conversion [0, 1]
  C: number; // Multi-thread reinforcement [0, 1]
  weightedR: number; // 100 * alphaR * R
  weightedA: number; // 100 * alphaA * A
  weightedV: number; // 100 * alphaV * V
  weightedC: number; // 100 * alphaC * C
}

export interface PartnerUtilityMetrics {
  placementId: string;
  entityId: string;
  entityName: string;
  coOwnershipO: number; // [0, 1]
  socialProofS: number; // [0, 1)
  incentiveFlagI: boolean;
  directCommitmentR: number; // [0, 1]
  amplificationA: number; // [0, 1]
  ownedConversionV: number; // [0, 1]
  multiThreadReinforcementC: number; // [0, 1]
  utilityScoreU: number; // [0, 100]
  utilityYieldEta: number; // U_i / max(1, outreachAttempts_i)
  decomposition: PartnerUtilityDecomposition;
  isApathyWarning: boolean;
}

export interface WorkbookUtilityReport {
  pui: number; // Workbook Partnership Utility Index [0, 100]
  actionsPerTouch: number; // Total confirmed actions / sum of touches
  inKindEquivalentPct: number; // In-kind asset equivalent % of target budget
  inKindEquivalentInr: number; // Total in-kind asset INR
  partners: Record<string, PartnerUtilityMetrics>;
  weights: UtilityStrategyWeights;
  strategyPreset: string;
}

export type WorkbookLike = {
  activeWorkbookId?: string;
  workbooks?: Record<string, { targetBudgetInr?: number; utilityWeights?: UtilityStrategyWeights }>;
  targetBudgetInr?: number;
  utilityWeights?: UtilityStrategyWeights;
  placements: Record<string, Placement>;
  branches: Record<string, Branch>;
};

/**
 * Normalizes utility strategy weights so alphaR + alphaA + alphaV + alphaC === 1.00.
 * Falls back to DEFAULT_UTILITY_WEIGHTS if sum is <= 0 or non-numeric.
 */
export function normalizeWeights(weights?: UtilityStrategyWeights): UtilityStrategyWeights {
  if (!weights) return DEFAULT_UTILITY_WEIGHTS;
  const rawSum = weights.alphaR + weights.alphaA + weights.alphaV + weights.alphaC;
  if (rawSum <= 0 || isNaN(rawSum)) {
    return DEFAULT_UTILITY_WEIGHTS;
  }
  if (Math.abs(rawSum - 1.0) < 0.001) {
    return weights;
  }
  return {
    ...weights,
    alphaR: weights.alphaR / rawSum,
    alphaA: weights.alphaA / rawSum,
    alphaV: weights.alphaV / rawSum,
    alphaC: weights.alphaC / rawSum,
  };
}

/**
 * 1. Revealed Co-Ownership Depth (O_i in [0, 1])
 * Ostrom's credible commitment index based on verifiable institutional behaviors:
 * written commitment, shared logo/branding, assigned staff, mobilized network.
 */
export function computeCoOwnershipDepth(signals?: CoOwnershipChecklist): number {
  if (!signals) return 0;
  const count =
    (signals.writtenCommitment ? 1 : 0) +
    (signals.brandOrLogoShared ? 1 : 0) +
    (signals.staffAssigned ? 1 : 0) +
    (signals.networkMobilized ? 1 : 0);
  return count / 4;
}

/**
 * 2. Social Proof / Screening Cost Reduction Factor (S_i in [0, 1))
 * Centola & Macy complex contagion curve modeling diminishing marginal friction:
 * S_i = 1 - 1 / (1 + k_in_Y(i))
 */
export function computeSocialProofFactor(yellowInDegree: number): number {
  const k = Math.max(0, yellowInDegree);
  return 1 - 1 / (1 + k);
}

/**
 * 3. Downstream Ecosystem Reach (D_reach_Y(i))
 * Count of unique non-root placements reachable strictly downstream from partner i
 * via confirmed (tick) yellow branches using Breadth-First Search (BFS).
 */
export function computeDownstreamAmplifierReach(
  placementId: string,
  placements: Record<string, Placement>,
  branches: Record<string, Branch>
): number {
  // Build adjacency list for confirmed yellow edges
  const adj: Record<string, string[]> = {};
  for (const br of Object.values(branches)) {
    if (br.type === 'yellow' && br.status === 'tick') {
      if (!adj[br.sourcePlacementId]) adj[br.sourcePlacementId] = [];
      adj[br.sourcePlacementId].push(br.targetPlacementId);
    }
  }

  const visited = new Set<string>();
  const queue: string[] = [placementId];
  visited.add(placementId);

  while (queue.length > 0) {
    const curr = queue.shift()!;
    const neighbors = adj[curr] || [];
    for (const next of neighbors) {
      if (!visited.has(next)) {
        visited.add(next);
        queue.push(next);
      }
    }
  }

  // Remove starting placement and any root NGO node from reach count
  visited.delete(placementId);
  for (const [id, plc] of Object.entries(placements)) {
    if (plc.isRootNgo) {
      visited.delete(id);
    }
  }

  return visited.size;
}

/**
 * 4. Partner Structural Utility (U_i in [0, 100])
 * Computes all 4 additive components for a single non-root partner placement.
 */
export function computePartnerUtility(
  placementId: string,
  workbook: WorkbookLike,
  entities: Record<string, Entity>,
  rootPlacementId: string
): PartnerUtilityMetrics {
  const placement = workbook.placements[placementId];
  if (!placement) {
    throw new Error(`Placement ${placementId} not found in workbook`);
  }

  const entity = entities[placement.entityId];
  const entityName = entity?.name || 'Unknown Partner';

  const activeWb =
    workbook.activeWorkbookId && workbook.workbooks
      ? workbook.workbooks[workbook.activeWorkbookId]
      : undefined;
  const rawWeights = workbook.utilityWeights || activeWb?.utilityWeights || DEFAULT_UTILITY_WEIGHTS;
  const weights = normalizeWeights(rawWeights);
  const branchesList = Object.values(workbook.branches);

  // Incoming confirmed yellow branches to placementId
  const yellowInBranches = branchesList.filter(
    (b) => b.targetPlacementId === placementId && b.type === 'yellow' && b.status === 'tick'
  );
  const yellowInDegree = yellowInBranches.length;

  // Co-ownership & Social proof
  const coOwnershipO = computeCoOwnershipDepth(placement.coOwnershipSignals);
  const socialProofS = computeSocialProofFactor(yellowInDegree);
  const incentiveFlagI = Boolean(placement.selectiveIncentives && placement.selectiveIncentives.length >= 1);

  // Public Choice Apathy Warning
  // Partner is pending without any selective incentive AND has zero social proof
  const hasIncomingActive = branchesList.some(
    (b) => b.targetPlacementId === placementId && (b.status === 'tick' || b.status === 'pending')
  );
  const hasConfirmedDirect = branchesList.some(
    (b) => b.targetPlacementId === placementId && (b.type === 'white' || b.type === 'green') && b.status === 'tick'
  );
  const isApathyWarning = !hasConfirmedDirect && hasIncomingActive && !incentiveFlagI && yellowInDegree === 0;

  // Direct Commitment Component (R_i in [0, 1])
  // Let w_i = 1 if there is a ticked white branch from Root NGO to i, else 0
  const hasTickedWhiteFromRoot = branchesList.some(
    (b) =>
      b.sourcePlacementId === rootPlacementId &&
      b.targetPlacementId === placementId &&
      b.type === 'white' &&
      b.status === 'tick'
  );
  const directCommitmentR = hasTickedWhiteFromRoot ? 0.50 + 0.50 * coOwnershipO : 0;

  // Ecosystem Brokerage / Amplification Component (A_i in [0, 1])
  // N_conf = count of unique non-root placements with at least one confirmed (tick) incoming branch of any color
  const confTargets = new Set<string>();
  for (const b of branchesList) {
    if (b.status === 'tick' && workbook.placements[b.targetPlacementId] && !workbook.placements[b.targetPlacementId].isRootNgo) {
      confTargets.add(b.targetPlacementId);
    }
  }
  const nConf = Math.max(1, confTargets.size);
  const reachCount = computeDownstreamAmplifierReach(placementId, workbook.placements, workbook.branches);
  const amplificationA = Math.min(1, reachCount / nConf);

  // Owned Conversion Contribution (V_i in [0, 1])
  // Ratio of outgoing ticked yellow targets that also hold a direct ticked white branch from Root NGO
  const directYellowTargets = branchesList
    .filter((b) => b.sourcePlacementId === placementId && b.type === 'yellow' && b.status === 'tick')
    .map((b) => b.targetPlacementId);

  let ownedConversionV = 0;
  if (directYellowTargets.length > 0) {
    const ownedCount = directYellowTargets.filter((targetId) =>
      branchesList.some(
        (b) =>
          b.sourcePlacementId === rootPlacementId &&
          b.targetPlacementId === targetId &&
          b.type === 'white' &&
          b.status === 'tick'
      )
    ).length;
    ownedConversionV = ownedCount / directYellowTargets.length;
  }

  // Multi-Thread Reinforcement Contribution (C_i in [0, 1])
  // Targets v with k_in_Y(v) >= 2 to which partner i supplies a confirmed yellow branch
  const multiThreadTargets = new Set<string>();
  for (const pId of Object.keys(workbook.placements)) {
    if (pId === rootPlacementId) continue;
    const inY = branchesList.filter(
      (b) => b.targetPlacementId === pId && b.type === 'yellow' && b.status === 'tick'
    ).length;
    if (inY >= 2) {
      multiThreadTargets.add(pId);
    }
  }

  let multiThreadReinforcementC = 0;
  if (multiThreadTargets.size > 0) {
    const suppliedCount = directYellowTargets.filter((targetId) => multiThreadTargets.has(targetId)).length;
    multiThreadReinforcementC = suppliedCount / multiThreadTargets.size;
  }

  // 4-Part Additive Utility Decomposition
  const weightedR = Number((100 * weights.alphaR * directCommitmentR).toFixed(2));
  const weightedA = Number((100 * weights.alphaA * amplificationA).toFixed(2));
  const weightedV = Number((100 * weights.alphaV * ownedConversionV).toFixed(2));
  const weightedC = Number((100 * weights.alphaC * multiThreadReinforcementC).toFixed(2));

  const utilityScoreU = Number(
    (100 * (weights.alphaR * directCommitmentR +
            weights.alphaA * amplificationA +
            weights.alphaV * ownedConversionV +
            weights.alphaC * multiThreadReinforcementC)).toFixed(1)
  );

  const outreachAttempts = Math.max(1, placement.outreachAttempts ?? 1);
  const utilityYieldEta = Number((utilityScoreU / outreachAttempts).toFixed(1));

  return {
    placementId,
    entityId: placement.entityId,
    entityName,
    coOwnershipO: Number(coOwnershipO.toFixed(2)),
    socialProofS: Number(socialProofS.toFixed(3)),
    incentiveFlagI,
    directCommitmentR: Number(directCommitmentR.toFixed(2)),
    amplificationA: Number(amplificationA.toFixed(2)),
    ownedConversionV: Number(ownedConversionV.toFixed(2)),
    multiThreadReinforcementC: Number(multiThreadReinforcementC.toFixed(2)),
    utilityScoreU,
    utilityYieldEta,
    decomposition: {
      R: Number(directCommitmentR.toFixed(2)),
      A: Number(amplificationA.toFixed(2)),
      V: Number(ownedConversionV.toFixed(2)),
      C: Number(multiThreadReinforcementC.toFixed(2)),
      weightedR,
      weightedA,
      weightedV,
      weightedC,
    },
    isApathyWarning,
  };
}

/**
 * 5. Complete Workbook Public Choice Utility Report
 * Computes PUI macro score, Buchanan-Tullock efficiency, in-kind asset value,
 * and individual utility scores for all non-root partner placements.
 */
export function computePublicChoiceUtilityReport(
  workbook: WorkbookLike,
  entities: Record<string, Entity>
): WorkbookUtilityReport {
  const placementsList = Object.values(workbook.placements);
  const branchesList = Object.values(workbook.branches);
  const rootPlacement = placementsList.find((p) => p.isRootNgo);
  const rootPlacementId = rootPlacement?.placementId || '';

  const activeWb =
    workbook.activeWorkbookId && workbook.workbooks
      ? workbook.workbooks[workbook.activeWorkbookId]
      : undefined;
  const rawWeights = workbook.utilityWeights || activeWb?.utilityWeights || DEFAULT_UTILITY_WEIGHTS;
  const weights = normalizeWeights(rawWeights);
  const partners: Record<string, PartnerUtilityMetrics> = {};

  // Compute metrics for all non-root partners
  for (const placement of placementsList) {
    if (placement.isRootNgo) continue;
    partners[placement.placementId] = computePartnerUtility(
      placement.placementId,
      workbook,
      entities,
      rootPlacementId
    );
  }

  // --- MACRO PUI COMPONENTS ---
  // 1. Direct Confirmation & Co-Ownership Realization (R_bar in [0, 1])
  // Mean of (0.50 + 0.50 O_i) across all resolved direct white outreach targets from Root NGO (cross = 0)
  const directWhiteTargets = branchesList.filter(
    (b) => b.sourcePlacementId === rootPlacementId && b.type === 'white' && (b.status === 'tick' || b.status === 'cross')
  );

  let rBar = 0;
  if (directWhiteTargets.length > 0) {
    let rSum = 0;
    for (const b of directWhiteTargets) {
      if (b.status === 'tick') {
        const targetPlacement = workbook.placements[b.targetPlacementId];
        const oDepth = computeCoOwnershipDepth(targetPlacement?.coOwnershipSignals);
        rSum += 0.50 + 0.50 * oDepth;
      }
      // Declined (cross) contributes 0
    }
    rBar = rSum / directWhiteTargets.length;
  }

  // 2. Owned Conversion Rate (V_bar in [0, 1])
  // Total referred nodes = unique nodes receiving at least 1 confirmed yellow branch
  const referredNodeIds = new Set<string>();
  for (const b of branchesList) {
    if (b.type === 'yellow' && b.status === 'tick') {
      const tgt = workbook.placements[b.targetPlacementId];
      if (tgt && !tgt.isRootNgo) {
        referredNodeIds.add(b.targetPlacementId);
      }
    }
  }

  const convertedNodeIds = new Set<string>();
  for (const refId of referredNodeIds) {
    const hasWhiteTick = branchesList.some(
      (b) => b.sourcePlacementId === rootPlacementId && b.targetPlacementId === refId && b.type === 'white' && b.status === 'tick'
    );
    if (hasWhiteTick) {
      convertedNodeIds.add(refId);
    }
  }

  const vBar = referredNodeIds.size > 0 ? convertedNodeIds.size / referredNodeIds.size : 0;

  // 3. Multi-Thread Depth Coverage (C_bar in [0, 1])
  // Nodes with k_in_Y >= 2 / max(1, Total Referred Nodes)
  let multiThreadCount = 0;
  for (const refId of referredNodeIds) {
    const inY = branchesList.filter(
      (b) => b.targetPlacementId === refId && b.type === 'yellow' && b.status === 'tick'
    ).length;
    if (inY >= 2) {
      multiThreadCount++;
    }
  }
  const cBar = referredNodeIds.size > 0 ? multiThreadCount / referredNodeIds.size : 0;

  // 4. Incentive Alignment Coverage (I_bar in [0, 1])
  // Fraction of active non-root partners with >= 1 articulated selective incentive OR k_in_Y >= 1
  const nonRootPlacements = placementsList.filter((p) => !p.isRootNgo);
  let alignedCount = 0;
  for (const plc of nonRootPlacements) {
    const hasIncentive = Boolean(plc.selectiveIncentives && plc.selectiveIncentives.length >= 1);
    const hasIncomingYellow = branchesList.some(
      (b) => b.targetPlacementId === plc.placementId && b.type === 'yellow' && b.status === 'tick'
    );
    if (hasIncentive || hasIncomingYellow) {
      alignedCount++;
    }
  }
  const iBar = nonRootPlacements.length > 0 ? alignedCount / nonRootPlacements.length : 0;

  // Workbook PUI (0 - 100)
  const pui = Number((100 * (0.35 * rBar + 0.25 * vBar + 0.20 * cBar + 0.20 * iBar)).toFixed(1));

  // Actions per Touch (Buchanan-Tullock efficiency)
  const totalTickedBranches = branchesList.filter((b) => b.status === 'tick').length;
  const totalTouches = nonRootPlacements.reduce((sum, p) => sum + Math.max(1, p.outreachAttempts ?? 1), 0);
  const actionsPerTouch = totalTouches > 0 ? Number((totalTickedBranches / totalTouches).toFixed(2)) : 0;

  // In-Kind Asset Equivalent
  const inKindEquivalentInr = branchesList.reduce((sum, b) => {
    if (b.type === 'white' && b.status === 'tick' && typeof b.inKindValueInr === 'number') {
      return sum + b.inKindValueInr;
    }
    return sum;
  }, 0);

  const targetBudgetInr = workbook.targetBudgetInr ?? activeWb?.targetBudgetInr ?? 0;
  const inKindEquivalentPct =
    targetBudgetInr > 0
      ? Number(((inKindEquivalentInr / targetBudgetInr) * 100).toFixed(1))
      : 0;

  return {
    pui,
    actionsPerTouch,
    inKindEquivalentPct,
    inKindEquivalentInr,
    partners,
    weights,
    strategyPreset: weights.presetName || 'balanced',
  };
}

/**
 * Convenient helper to compute a workbook's Public Choice utility report
 * directly from workspace state and workbookId.
 */
export function computeWorkbookUtilityReport(
  workspace: WorkspaceState,
  workbookId: string
): WorkbookUtilityReport {
  const wb = workspace.workbooks[workbookId];
  const wbContext: WorkbookLike = {
    ...workspace,
    activeWorkbookId: workbookId,
    utilityWeights: wb?.utilityWeights,
    targetBudgetInr: wb?.targetBudgetInr,
  };
  return computePublicChoiceUtilityReport(wbContext, workspace.entities);
}

/**
 * QualCount: Visual Multiplex Partnership Management System
 * Normalized Relational Schema (Version 2)
 * 
 * Maps 1-to-1 with Phase 2 Rust / SQLite relational schema and
 * portable Workspace Folder JSON contracts.
 * All collections are normalized records keyed by UUID/ID strings.
 * All dates are ISO 8601 strings for Rust Serde compatibility.
 */

export type WorkspaceSourceType = 'local' | 'gdrive';

export type EntityCategory =
  | 'ngo'
  | 'csr'
  | 'government'
  | 'institution'
  | 'community'
  | 'other'
  | (string & {});

export type BranchType = 'green' | 'white' | 'yellow';
// green  = Financial / CSR funding only
// white  = Direct working relationship (venue, attendance, co-host, goodwill)
// yellow = Network bridge / referral / amplification gateway

export type BranchStatus = 'pending' | 'tick' | 'cross';
// pending = Planned outreach or awaiting reply (dashed normal hue)
// tick    = Verified partner action / commitment (solid glowing/ink hue)
// cross   = Declined / stalled outreach (faded gray or grayish-green)

export type SelectiveIncentiveTag =
  | 'csr_compliance'
  | 'brand_visibility'
  | 'institutional_mandate'
  | 'policy_influence'
  | 'network_prestige'
  | 'asset_activation'
  | 'community_legitimacy';

export interface CoOwnershipChecklist {
  writtenCommitment: boolean;
  brandOrLogoShared: boolean;
  staffAssigned: boolean;
  networkMobilized: boolean;
}

export interface UtilityStrategyWeights {
  presetName: 'balanced' | 'amplification' | 'delivery' | 'custom';
  alphaR: number; // Direct commitment & co-ownership (default 0.30)
  alphaA: number; // Ecosystem brokerage / amplification (default 0.35)
  alphaV: number; // Owned relationship conversion (default 0.20)
  alphaC: number; // Multi-thread reinforcement (default 0.15)
}

export const DEFAULT_UTILITY_WEIGHTS: UtilityStrategyWeights = {
  presetName: 'balanced',
  alphaR: 0.30,
  alphaA: 0.35,
  alphaV: 0.20,
  alphaC: 0.15,
};

export const UTILITY_PRESETS: Record<'balanced' | 'amplification' | 'delivery', UtilityStrategyWeights> = {
  balanced: {
    presetName: 'balanced',
    alphaR: 0.30,
    alphaA: 0.35,
    alphaV: 0.20,
    alphaC: 0.15,
  },
  amplification: {
    presetName: 'amplification',
    alphaR: 0.20,
    alphaA: 0.45,
    alphaV: 0.15,
    alphaC: 0.20,
  },
  delivery: {
    presetName: 'delivery',
    alphaR: 0.50,
    alphaA: 0.20,
    alphaV: 0.20,
    alphaC: 0.10,
  },
};

